    /** A grade's rates on the sheet. */
    List<Rate> findBySheetIdAndGrade(String sheetId, String grade);

    /** A grade's rate from a from-date; a null from-date finds the one with none. */
    Optional<Rate> findBySheetIdAndGradeAndFrom(String sheetId, String grade, LocalDate from);
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.rollup.RollupService.Snapshot;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class RateService {

    private final RateRepository rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final Audit audit;

    public RateService(RateRepository rates, SheetService sheets, RollupService rollup, Audit audit) {
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates by grade, then from-date; a grade without one has no rate. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        sheets.today(sheetId); // the sheet must exist
        return rates.findBySheetId(sheetId).stream()
                .sorted(Comparator.comparing(Rate::getGrade).thenComparing(Rate.BY_FROM))
                .toList();
    }

    /** Set the rate for a grade from a from-date (none: from the beginning of time), replacing any it had
     * from that date. */
    @Transactional
    public Rate set(String user, String sheetId, String grade, LocalDate from, BigDecimal pct) {
        sheets.today(sheetId); // the sheet must exist
        BigDecimal value = pct.setScale(2);
        Snapshot before = rollup.snapshot(sheetId);
        Rate rate = rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, value));
        } else {
            rate.setRate(value);
            rates.flush();
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + grade
                + " rate=" + value.toPlainString() + (from != null ? " from=" + from : ""));
        rollup.recordChanges(user, sheetId, before);
        return rate;
    }
}
-- The rate for each grade on a sheet: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A rate can carry a from-date: a grade may have several rates, one per from-date, and a rate with
-- no from-date applies from the beginning of time. A rate is kept by its own id.
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY;
ALTER TABLE rate ADD PRIMARY KEY (id);
ALTER TABLE rate ADD CONSTRAINT rate_sheet_grade_from UNIQUE NULLS NOT DISTINCT (sheet_id, grade, from_date);
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Session } from '../../core/session';
import { Grade } from '../people/people-api';

export interface Rate {
  grade: Grade;
  /** The date (yyyy-mm-dd) the rate is in force from; null for from the beginning of time. */
  from: string | null;
  /** A percent with two decimals, e.g. "12.50". */
  rate: string;
}

/**
 * The rate a grade has in force on a date (yyyy-mm-dd): the one with the latest from-date on or
 * before it; none when the date is before every rate of the grade.
 */
export function rateOn(rates: readonly Rate[], grade: Grade, date: string): string | undefined {
  // No from-date sorts as '', before every date.
  let best: Rate | undefined;
  for (const r of rates) {
    const from = r.from ?? '';
    if (r.grade === grade && from <= date && (!best || from > (best.from ?? ''))) best = r;
  }
  return best?.rate;
}

/** Shown in place of a due whose grade has no rate. */
export const NO_RATE = 'n/a';

/** Hundredths of a decimal with up to two decimals, e.g. "12.5" is 1250 and "-0.3" is -30. */
export function hundredths(value: string): bigint {
  const negative = value.startsWith('-');
  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
  const abs = BigInt(whole) * 100n + BigInt(frac.padEnd(2, '0'));
  return negative ? -abs : abs;
}

/** Hundredths as a decimal with two decimals, e.g. -30 is "-0.30". */
export function fromHundredths(value: bigint): string {
  const abs = value < 0n ? -value : value;
  return `${value < 0n ? '-' : ''}${abs / 100n}.${String(abs % 100n).padStart(2, '0')}`;
}

/**
 * What is due on an amount at a rate: the amount times the rate, divided by 100, rounded to two
 * decimals, a half to the even cent, or up when `halfUp`. Worked in whole numbers so no rounding
 * creeps in; n/a when there is no rate.
 */
export function dueOf(amount: string, rate: string | undefined, halfUp = false): string {
  if (rate === undefined) return NO_RATE;
