  /** What is due on a claim of the person's, at the grade they have on the claim's date. */
  private claimDue(claim: Claim, person: Person): string {
    return claimDue(claim, this.rates(), gradeOn(person.grades, claim.date), this.floor.value(), this.late(),
      roundsBy(claim, this.claimsOf(person.id)));
  }

  /** The sum of the dues of the claims the person has that count (n/a ones skipped), 0.00 with none. A
   * person shows n/a when neither the grade they have on the sheet's today nor one they had on the date of a
   * claim that counts has a rate in force on the sheet's today, unless a settled or stated claim keeps a
   * figure. */
  protected personDueTotal(person: Person): string {
    const counted = this.claimsOf(person.id).filter((c) => this.countsLive(c));
    const frozen = counted.some(keepsFigure);
    const grades = [this.gradeToday(person), ...counted.map((c) => gradeOn(person.grades, c.date))];
    if (!grades.some((g) => g !== undefined && this.rateByGrade().has(g)) && !frozen) return NO_RATE;
    return sumAmounts(counted.map((c) => this.claimDue(c, person)).filter((d) => d !== NO_RATE));
  }

  /** The person's claims that count and are overdue. */
  protected overdueOf(person: Person): Claim[] {
    const today = this.session.today();
     * Take a statement for a person: record their due-total now, late charges included, and bind each of their
     * claims that counts (OPEN and PENDING ones within a hold, unbound, do not) to the figure it has now (never its late charge, which keeps following the sheet's
     * today); a claim of theirs that does not count is left unbound.
     */
    @Transactional
    public Person take(String user, String sheetId, Long personId) {
        LocalDate today = sheets.today(sheetId);
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
        Snapshot before = rollup.snapshot(sheetId);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean fixed = false;
        List<Claim> counted = new ArrayList<>();
        for (Claim claim : claims.findBySheetIdAndPersonId(sheetId, personId)) {
            if (!RollupService.counts(claim, person)) {
                claim.unbind();
                continue;
            }
            BigDecimal figure = claimService.figureOf(claim, person);
            BigDecimal due = rollup.dueOf(claim, person);
            fixed |= RollupService.keepsFigure(claim);
            claim.bind(figure);
            counted.add(claim);
            if (due != null) {
                total = total.add(due);
            }
        }
        // Like the screen: with no rate in force today and no claim keeping a figure, the due-total is n/a.
        boolean rated = rollup.rated(person, counted, today);
        BigDecimal dueTotal = rated || fixed ? total : null;
        claims.flush();
        statements.saveAndFlush(new Statement(sheetId, personId, today, user, dueTotal, counted.size()));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal != null ? dueTotal.toPlainString() : "n/a")
                + " claims=" + counted.size());
        rollup.recordChanges(user, sheetId, before);
        return person;
    }
}

